<?php
declare(strict_types=1);require_once dirname(__DIR__,2).'/bootstrap.php';
use Artdon\MaterialCenter\Adapters\LegacyAuthAdapter;use Artdon\MaterialCenter\Security\PermissionService;use Artdon\MaterialCenter\Services\DocumentService;
try{$user=(new LegacyAuthAdapter())->current();$permission=new PermissionService();$service=new DocumentService();if($_SERVER['REQUEST_METHOD']==='GET'&&in_array(($_GET['action']??''),['download','preview'],true)){$permission->require($user,'material_center.view');$file=$service->version((int)($_GET['id']??0));if($file['access_level']==='engineering')$permission->require($user,'material_center.documents.manage');if($file['access_level']==='purchasing')$permission->require($user,'material_center.purchase_price.view');$preview=($_GET['action']??'')==='preview'&&in_array($file['mime_type'],['application/pdf','image/png','image/jpeg','image/webp'],true);while(ob_get_level())ob_end_clean();header('Content-Type: '.$file['mime_type']);header('Content-Disposition: '.($preview?'inline':'attachment').'; filename="'.rawurlencode($file['file_name']).'"');header('Content-Length: '.$file['file_size']);header('X-Content-Type-Options: nosniff');header("Content-Security-Policy: default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'");readfile($file['file_path']);exit;}header('Content-Type:application/json;charset=utf-8');$permission->require($user,'material_center.documents.manage');if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf((string)($_POST['csrf_token']??'')))throw new RuntimeException('安全令牌已过期。',419);$action=(string)($_POST['action']??'upload');if($action==='upload')$data=['id'=>$service->upload($_FILES['file']??[],$_POST,$user->id)];elseif($action==='delete'){$service->delete((int)$_POST['id'],$user->id);$data=[];}else throw new RuntimeException('操作无效。');echo json_encode(['ok'=>true,'data'=>$data],JSON_UNESCAPED_UNICODE);}
catch(Throwable$e){if(!headers_sent())header('Content-Type:application/json;charset=utf-8');http_response_code($e->getCode()>=400&&$e->getCode()<600?$e->getCode():422);echo json_encode(['ok'=>false,'message'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
